const textBlock = document.getElementById('post-body-content').innerText;
const words = textBlock.trim().split(/\s+/).length;
const time = Math.ceil(words / 225);
document.getElementById('read-time-calc').innerHTML = `<i class='bi bi-book me-1'></i> ${time} min de leitura`;
